def _off_by_one_slice_k_minus_one(self, source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Slice) and isinstance(node.upper, ast.BinOp) and isinstance(node.upper.op, ast.Sub):
            if isinstance(node.upper.right, ast.Constant) and node.upper.right.value == 1:
                out.append(_splice(source, node.upper, _name_text(source, node.upper.left)))
    return out

def _comparison_2_to_1_rule(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare) and len(node.ops) == 1:
            if isinstance(node.comparators[0], ast.Constant) and node.comparators[0].value == 2:
                lefts, le = _span(source, node.left)
                rs, re = _span(source, node.comparators[0])
                new_text = f"{source[lefts:le]} == 1"
                out.append(_splice(source, node, new_text))
    return out

# ----------------------------------------------------------------------
# Rule: append() called on undefined object name -> the real accumulator
# ----------------------------------------------------------------------
def fix_undefined_accumulator(source):
    tree = _parse(source)
    if tree is None:
        return []
    out = []
    for func in _funcs(tree):
        bound = _collect_bound_names(func)
        list_inits = []
        for node in ast.walk(func):
            if (isinstance(node, ast.Assign) and len(node.targets) == 1
                    and isinstance(node.targets[0], ast.Name)
                    and isinstance(node.value, ast.List) and len(node.value.elts) == 0):
                list_inits.append(node.targets[0].id)
        if not list_inits:
            continue
        for node in ast.walk(func):
            if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                    and node.func.attr == 'append' and isinstance(node.func.value, ast.Name)):
                vname = node.func.value.id
                if vname not in bound:
                    cands = difflib.get_close_matches(vname, list_inits, n=1, cutoff=0.0) or list_inits
                    out.append(_splice(source, node.func.value, cands[0]))
    return out

