def _while_self_increment_to_increment_by_one(self, source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.AugAssign) and isinstance(node.op, ast.Add):
            tgt = ast.get_source_segment(source, node.target)
            val = ast.get_source_segment(source, node.value)
            if tgt and val and tgt == val:
                out.append(_replace_node(source, node.value, "1"))
    return out

# ---------------------------------------------------------------------------
# Rule E: unique_date typo call -> unique_day
# ---------------------------------------------------------------------------
def _typo_call_fix(source):
    tree = _parse(source)
    if tree is None:
        return []
    defined = {n.name for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)}
    if 'unique_day' not in defined:
        return []
    edits = []
    for n in ast.walk(tree):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name):
            if n.func.id == 'unique_date' and 'unique_date' not in defined:
                s, e = _span(source, n.func)
                edits.append((s, e, 'unique_day'))
    if not edits:
        return []
    return [_multi_splice(source, edits)]

