rule_code:
@_safe
def _rule_typo_uppercase(source):
    """`.uppercase()` is not a real str method (typo for `.upper()`),
    causes AttributeError at run time."""
    tree = ast.parse(source)
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Attribute) and node.attr == "uppercase":
            s, e = _span(source, node)
            attr_len = len(node.attr)
            attr_s = e - attr_len
            candidate = source[:attr_s] + "upper" + source[e:]
            if candidate != source:
                out.append(candidate)
    return out

@_safe
def fix_return_variable(source):
    """`return` of the wrong variable instead of the accumulator list."""
    tree = ast.parse(source)
    out = []
    for fn in [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)]:
        acc = _find_function_accumulator(fn)
        if not acc:
            continue
        for node in ast.walk(fn):
            if isinstance(node, ast.Return) and isinstance(node.value, ast.Name):
                if node.value.id != acc:
                    out.append(_splice(source, node.value, acc))
    return _dedupe(out)

