rule_code:
def fix_remove_before_append_order(source):
    tree = _parse(source)
    if tree is None:
        return []
    out = []
    for node in ast.walk(tree):
        body = getattr(node, 'body', None)
        if not isinstance(body, list):
            continue
        for i in range(len(body) - 1):
            s1, s2 = body[i], body[i + 1]
            if _is_call(s1, 'remove') and _is_call(s2, 'append'):
                l1 = s1.value.args[0].args[0].id
                l2 = s2.value.args[0].args[0].id
                if l1 == l2:
                    s1s, s1e = _span(source, s1)
                    s2s, s2e = _span(source, s2)
                    t1 = source[s1s:s1e]
                    t2 = source[s2s:s2e]
                    indent = ' ' * s1.col_offset
                    new_text = t2 + '\n' + indent + t1
                    out.append(source[:s1s] + new_text + source[s2e:])
    return out

def _range_off_by_one(source):
    """range(..., len(x) - 1) that drops the last character -> remove the -1."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "range":
            args = node.args
            target = None
            if len(args) == 1:
                target = args[0]
            elif len(args) == 2:
                target = args[1]
            if (target is not None and isinstance(target, ast.BinOp) and isinstance(target.op, ast.Sub)
                    and isinstance(target.right, ast.Constant) and target.right.value == 1
                    and isinstance(target.left, ast.Call) and isinstance(target.left.func, ast.Name)
                    and target.left.func.id == "len"):
                ls, le = _span(source, target.left)
                out.append(_splice(source, target, source[ls:le]))
    return out

@_safe
def unwrap_mutator_assign(source):
    """`x = x.append(y)` (or augassign) assigns None; keep just the call."""
    tree = ast.parse(source)
    out = []
    mutators = {'append', 'remove', 'extend', 'insert', 'pop', 'sort', 'reverse'}
    for node in ast.walk(tree):
        if isinstance(node, (ast.Assign, ast.AugAssign)):
            value = node.value
            if isinstance(value, ast.Call) and isinstance(value.func, ast.Attribute) \
               and value.func.attr in mutators:
                vs, ve = _span(source, value)
                call_src = source[vs:ve]
                out.append(_splice(source, node, call_src))
    return _dedupe(out)

