# ----------------------------------------------------------------------
# Rule: recursive merge-sort slices the parameter directly instead of
# recursing on it (`lst1 = lst[:mid]` should be `lst1 = sort_age(lst[:mid])`)
# ----------------------------------------------------------------------
def _wrap_unrecursed_slice(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for func in tree.body:
        if not isinstance(func, ast.FunctionDef) or not func.args.args:
            continue
        is_recursive = any(
            isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == func.name
            for n in ast.walk(func) if n is not func
        )
        if not is_recursive:
            continue
        param = func.args.args[0].arg
        for node in ast.walk(func):
            if isinstance(node, ast.Assign) and isinstance(node.value, ast.Subscript):
                sub = node.value
                if (isinstance(sub.value, ast.Name) and sub.value.id == param
                        and isinstance(sub.slice, ast.Slice)):
                    s, e = _span(source, sub)
                    text = source[s:e]
                    out.append(source[:s] + f"{func.name}({text})" + source[e:])
    return out

def _fix_contains_unique_day_return_unique_day(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Return) and isinstance(node.value, ast.Name) and node.value.id in {"unique_date", "unique_month"}:
            out.append(_splice(source, node, "return False"))
    return out

def _forget_to_return_result(self, source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for func in [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name == "top_k"]:
        if not func.body:
            continue
        last = func.body[-1]
        if not isinstance(last, ast.Return):
