def _missing_round(source):
    """A bare `X // 3` used directly as a printed value, with no rounding
    logic (comparison to 2 mod 3) present anywhere in the program."""
    if re.search(r'%\s*3\s*(==|>=)\s*2', source):
        return []
    if 'round(' in source or 'ceil(' in source:
        return []
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    candidates = _find_print_candidates(tree)
    out = []
    for stmt in candidates:
        call = stmt.value
        e1, e2 = _extract_two_exprs(call)
        for e in (e1, e2):
            if e is None:
                continue
            if isinstance(e, ast.BinOp) and isinstance(e.op, ast.FloorDiv) \
               and isinstance(e.right, ast.Constant) and e.right.value == 3:
                num_s, num_e = _span(source, e.left)
                numer = source[num_s:num_e]
                replacement = "(%s // 3 + (1 if %s %% 3 == 2 else 0))" % (numer, numer)
                out.append(_splice(source, e, replacement))
    return out

def _rule_fix_pop_index_arg(source):
    """Replace pop subscript/variable misuse with a proper index or element."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "pop":
            if node.args and isinstance(node.args[0], ast.Subscript):
                out.append(_splice(source, node.args[0], "index"))
    return out

def _append_variable_instead_of_constant_or_value(self, source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "append":
            if len(node.args) != 1:
                continue
            arg = node.args[0]
            if isinstance(arg, ast.Name):
                if _name_text(source, arg) != _name_text(source, node.func.value):
                    out.append(_splice(source, arg, _name_text(source, node.func.value)))
            elif isinstance(arg, ast.Constant):
                if isinstance(node.func.value, ast.Name):
                    out.append(_splice(source, arg, _name_text(source, node.func.value)))
    return out

