def _rule_fix_assignment_swap(source):
    """Repair broken two-step swaps into tuple swap."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and len(node.targets) == 1:
            t = node.targets[0]
            if isinstance(t, ast.Subscript) and isinstance(node.value, ast.Subscript):
                parent = None
                for n in ast.walk(tree):
                    if isinstance(n, ast.FunctionDef) and any(node is b for b in n.body):
                        parent = n
                        break
                if parent:
                    out.append(_splice(source, node, f"{source[_span(source, t)[0]:_span(source, t)[1]]}, {source[_span(source, node.value)[0]:_span(source, node.value)[1]]} = {source[_span(source, node.value)[0]:_span(source, node.value)[1]]}, {source[_span(source, t)[0]:_span(source, t)[1]]}"))
    return out

def _membership_against_input_instead_of_output(self, source):
    tree = self._parse(source)
    if tree is None:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare) and len(node.ops) == 1 and isinstance(node.ops[0], ast.NotIn):
            if isinstance(node.comparators[0], ast.Name) and node.comparators[0].id == "lst":
                out.append(_splice(source, node.comparators[0], "new_lst" if "new_lst" in source else "output"))
            elif isinstance(node.comparators[0], ast.Name) and node.comparators[0].id in {"list", "new", "newlist", "newseq", "keep", "a", "pst", "sumx", "seen"}:
                continue
    return list(dict.fromkeys(out))

