def _fix_input_to_int(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    _attach_parents(tree)
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "input":
            out.append(_splice(source, node, "int(input())"))
    return out

def _wrong_limit_comparison(self, source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare) and len(node.ops) == 1:
            op = node.ops[0]
            if isinstance(op, ast.LtE):
                out.append(_splice(source, node, f"{_name_text(source, node.left)} < {_name_text(source, node.comparators[0])}"))
            elif isinstance(op, ast.GtE):
                out.append(_splice(source, node, f"{_name_text(source, node.left)} > {_name_text(source, node.comparators[0])}"))
    return out

def _str_literal_to_int_when_call(source):
    """Comparing the result of a call (e.g. len(...)) to string '4'/'7' instead of int."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    edits = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare) and isinstance(node.left, ast.Call):
            for op, comp in zip(node.ops, node.comparators):
                if isinstance(op, (ast.Eq, ast.Is)) and isinstance(comp, ast.Constant) and comp.value in ("4", "7"):
                    edits.append(comp)
    if not edits:
        return []
    edits_sorted = sorted(edits, key=lambda n: _span(source, n)[0], reverse=True)
    new_source = source
    for comp in edits_sorted:
        new_source = _splice(new_source, comp, comp.value)
    return [new_source]

