rule_code:
def _typo_mod26_to_36(source):
    """`X % 26` (or `X // 26`) is almost certainly a mistyped 36 in this
    feet/inch domain."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Mod, ast.FloorDiv)):
            right = node.right
            if isinstance(right, ast.Constant) and right.value == 26:
                s, e = _span(source, right)
                out.append(source[:s] + "36" + source[e:])
    return out

def _fix_bad_augassign(source):
    """`x =+ 1` (parsed as x = +1) typo'd for `x += 1`."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            val = node.value
            if isinstance(val, ast.UnaryOp) and isinstance(val.op, ast.UAdd) and isinstance(val.operand, ast.Constant):
                target_name = node.targets[0].id
                new_text = f"{target_name} += {val.operand.value}"
                out.append(_splice(source, node, new_text))
    return out

# ----------------------------------------------------------------------
# Rule: undefined name used as append/remove arg after a tracker for-loop
# ----------------------------------------------------------------------
def fix_undefined_ref_after_tracker_loop(source):
    tree = _parse(source)
    if tree is None:
        return []
    out = []
    for func in _funcs(tree):
        bound = _collect_bound_names(func)
        for node in ast.walk(func):
            if isinstance(node, ast.While):
                tracker = None
                for stmt in node.body:
                    if (isinstance(stmt, ast.Assign) and len(stmt.targets) == 1
                            and isinstance(stmt.targets[0], ast.Name)):
                        tracker = stmt.targets[0].id
                        break
                if tracker is None:
                    continue
                for sub in ast.walk(node):
                    if (isinstance(sub, ast.Call) and isinstance(sub.func, ast.Attribute)
                            and sub.func.attr in ('append', 'remove') and len(sub.args) == 1
                            and isinstance(sub.args[0], ast.Name)):
                        argname = sub.args[0].id
                        if argname not in bound and argname != tracker:
                            out.append(_splice(source, sub.args[0], tracker))
    return out

