def _fix_bool_or_numeric_confusion(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.BoolOp) and isinstance(node.op, ast.Or):
            values = node.values
            if len(values) == 2:
                a, b = values
                if isinstance(a, ast.Compare) and isinstance(b, ast.Compare):
                    if ast.dump(a.left) == ast.dump(b.left) and len(a.ops) == len(b.ops) == 1:
                        sa, ea = _span(source, a)
                        sb, eb = _span(source, b)
                        if source[sa:ea] != source[sb:eb]:
                            continue
                        out.append(_splice(source, node, source[sa:ea] + " in {4, 7}"))
    return out

def _wrong_list_variable_return(self, source):
    tree = self._parse(source)
    if tree is None:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Return) and isinstance(node.value, ast.Name):
            if node.value.id in {"x", "i", "e", "element"}:
                out.append(_splice(source, node.value, "new_lst" if "new_lst" in source else "output"))
            if node.value.id == "lst":
                out.append(_splice(source, node.value, "new_list" if "new_list" in source else "output"))
    return list(dict.fromkeys(out))

@_safe
def add_missing_call_parens(source):
    """`x.pop` / `x.reverse` used as a statement or return value without `()`."""
    tree = ast.parse(source)
    out = []
    mutators = {'append', 'pop', 'extend', 'remove', 'reverse', 'insert', 'sort'}
    for node in ast.walk(tree):
        target = None
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Attribute):
            target = node.value
        elif isinstance(node, ast.Return) and isinstance(node.value, ast.Attribute):
            target = node.value
        if target is not None and target.attr in mutators:
            s, e = _span(source, target)
            out.append(_splice(source, target, source[s:e] + "()"))
    return _dedupe(out)

