def _float_round_to_inch_rule(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "round":
            if len(node.args) == 1 and isinstance(node.args[0], ast.BinOp) and isinstance(node.args[0].op, ast.Div):
                div = node.args[0]
                if isinstance(div.right, ast.Constant) and div.right.value == 3:
                    ls, le = _span(source, div.left)
                    new_text = f"round({source[ls:le]}/3)"
                    out.append(_splice(source, node, new_text))
    return out

def _fix_newseq_before_use(self, source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.If):
            seg = ast.get_source_segment(source, node.test) or ""
            if "newseq[-1] < x" in seg:
                out.append(_replace_node(source, node.test, "seq[-1] < x"))
    return out

def _list_method_call_parentheses_and_item(self, source):
    tree = self._parse(source)
    if tree is None:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Attribute) and node.attr == "append":
            parent = ast.get_source_segment(source, node)
            if parent and ".append" in parent:
                out.append(source.replace(".append.item", ".append(item)").replace(".append[element]", ".append(element)").replace(".append[entry]", ".append(entry)").replace(".append[ i ]", ".append(i)"))
        if isinstance(node, ast.Subscript):
            seg = ast.get_source_segment(source, node)
            if seg and "count[" in seg:
                out.append(source.replace("count[entry]", "count(entry)").replace("output.count[entry]", "output.count(entry)"))
    return list(dict.fromkeys(out))

