def _self_name_instead_of_param(source):
    """A helper function erroneously compares its own name (instead of its
    parameter) inside its body, e.g. `if roundI == 1:` inside def roundI(inch)."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    call_funcs = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            call_funcs.add(id(node.func))
    out = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.FunctionDef):
            continue
        fname = node.name
        params = [a.arg for a in node.args.args]
        if not params:
            continue
        first_param = params[0]
        for inner in ast.walk(node):
            if isinstance(inner, ast.Name) and inner.id == fname \
               and inner.id != first_param and id(inner) not in call_funcs:
                s, e = _span(source, inner)
                out.append(source[:s] + first_param + source[e:])
    return out

def _rule_basic_misapplied_capitalize(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if node.func.attr == "capitalize":
                txt = ast.get_source_segment(source, node)
                if txt and ".capitalize()" in txt:
                    out.append(_replace_node(source, node, txt.replace(".capitalize()", ".swapcase()")))
    return out

def _fix_unique_day_comparison(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare) and len(node.ops) == 1 and isinstance(node.ops[0], ast.Eq):
            left = node.left
            right = node.comparators[0]
            if isinstance(left, ast.Name) and isinstance(right, ast.Name):
                if (left.id, right.id) in {("day", "days"), ("days", "day"), ("day", "days_in_month"), ("days_in_month", "day")}: 
                    ls, le = _span(source, left)
                    rs, re = _span(source, right)
                    new_cmp = source[ls:le] + " == " + source[rs:re]
                    out.append(_splice(source, node, new_cmp))
    return out

def _rule_sort_return_sort_name(source):
    """Repair returning the built-in sort function or a missing final list."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Return) and isinstance(node.value, ast.Name):
            if node.value.id == "sort":
                out.append(_splice(source, node.value, "sortt"))
            if node.value.id in {"new_list", "sorted_lst", "output", "result", "newlst", "sort1"}:
                continue
    return out

