        if not fn.body:
            continue
        if _has_any_return(fn):
            continue
        last_stmt = fn.body[-1]
        _, e = _span(source, last_stmt)
        indent = ' ' * last_stmt.col_offset
        insertion = "\n" + indent + "return %s" % acc
        out.append(source[:e] + insertion + source[e:])
    return _dedupe(out)

