    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Return) and isinstance(node.value, ast.Name):
            if node.value.id == "False":
                out.append(_splice(source, node.value, "0"))
            elif node.value.id == "True":
                out.append(_splice(source, node.value, "1"))
    return out

def _fix_mod_zero_one_two_rule(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.If):
            test = node.test
            if isinstance(test, ast.Compare) and len(test.ops) == 1 and isinstance(test.ops[0], ast.Eq):
                if isinstance(test.comparators[0], ast.Constant) and test.comparators[0].value == 2:
                    ls, le = _span(source, test.left)
                    new_test = f"{source[ls:le]} == 2"
                    out.append(_splice(source, test, new_test))
    return out

def _fix_count_not_len(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare) and len(node.ops) == 1 and isinstance(node.ops[0], ast.Eq):
            left = node.left
            right = node.comparators[0]
            if isinstance(left, ast.Name) and isinstance(right, ast.Call):
                if isinstance(right.func, ast.Name) and right.func.id == "len":
                    out.append(_splice(source, node, source[_span(source, left)[0]:_span(source, left)[1]] + " in {4, 7}"))
