def _rule_zero_branch_missing_else(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.If) and node.orelse == []:
            body_text = ast.get_source_segment(source, node)
            if body_text and "print(" in body_text and "swapcase()" in body_text:
                continue
            if body_text and "print(" in body_text:
                # add an else by local splice only when the body is a single print and the guard is malformed
                test_text = ast.get_source_segment(source, node.test)
                if test_text and ("[1:].isupper()" in test_text or "[1:].lower()" in test_text or ".lower()" in test_text or ".title()" in test_text):
                    indent = " " * node.col_offset
                    stmt = ast.get_source_segment(source, node.body[0])
                    new = body_text + f"\n{indent}else:\n{indent}    print({ast.get_source_segment(source, node.body[0].value.args[0]) if isinstance(node.body[0], ast.Expr) and isinstance(node.body[0].value, ast.Call) and node.body[0].value.args else ast.get_source_segment(source, node.body[0]).split('print(',1)[1].rsplit(')',1)[0]})"
                    out.append(_replace_node(source, node, new))
                    break
    return out

def _remove_max_then_append_max(self, source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call):
            call = node.value
            if isinstance(call.func, ast.Attribute) and call.func.attr == "remove":
                if len(call.args) == 1 and isinstance(call.args[0], ast.Call):
                    inner = call.args[0]
                    if isinstance(inner.func, ast.Name) and inner.func.id == "max":
                        out.append(_splice(source, call.args[0], _name_text(source, call.args[0])))
    return out

def _fix_boolop_logic(source):
    """De Morgan slip: `x != a or x != b` (always true) should be `and`;
    `x == a and x == b` (always false) should be `or`."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.BoolOp) and len(node.values) == 2:
            a, b = node.values
            if (isinstance(a, ast.Compare) and isinstance(b, ast.Compare)
                    and len(a.ops) == 1 and len(b.ops) == 1
                    and isinstance(a.left, ast.Name) and isinstance(b.left, ast.Name)
                    and a.left.id == b.left.id):
                opa, opb = a.ops[0], b.ops[0]
                la_s, la_e = _span(source, a)
                lb_s, lb_e = _span(source, b)
                if isinstance(node.op, ast.Or) and isinstance(opa, ast.NotEq) and isinstance(opb, ast.NotEq):
                    new_full = source[la_s:la_e] + " and " + source[lb_s:lb_e]
                    out.append(_splice(source, node, new_full))
                elif isinstance(node.op, ast.And) and isinstance(opa, ast.Eq) and isinstance(opb, ast.Eq):
                    new_full = source[la_s:la_e] + " or " + source[lb_s:lb_e]
                    out.append(_splice(source, node, new_full))
    return out

