# Rule: append(raw_list) when the max value was just computed separately
# ----------------------------------------------------------------------
def fix_append_raw_list_instead_of_max(source):
    tree = _parse(source)
    if tree is None:
        return []
    out = []
    for func in _funcs(tree):
        for node in ast.walk(func):
            body = getattr(node, 'body', None)
            if not isinstance(body, list):
                continue
            last_max_assign = None
            for stmt in body:
                if (isinstance(stmt, ast.Assign) and len(stmt.targets) == 1
                        and isinstance(stmt.targets[0], ast.Name)
                        and isinstance(stmt.value, ast.Call)
                        and isinstance(stmt.value.func, ast.Name) and stmt.value.func.id == 'max'
                        and len(stmt.value.args) == 1 and isinstance(stmt.value.args[0], ast.Name)):
                    last_max_assign = (stmt.targets[0].id, stmt.value.args[0].id)
                for sub in ast.walk(stmt):
                    if (isinstance(sub, ast.Call) and isinstance(sub.func, ast.Attribute)
                            and sub.func.attr == 'append' and len(sub.args) == 1
                            and isinstance(sub.args[0], ast.Name) and last_max_assign):
                        varname, listname = last_max_assign
                        if sub.args[0].id == listname:
                            out.append(_splice(source, sub.args[0], varname))
    return out

# ----------------------------------------------------------------------
# Rule: undefined name used in the statements following the inner
# for-loop (typically `lst.remove(X)` / `result.append(X)`) that should
# reference the variable tracked by `TRACK = lst[0]` at loop start
# ----------------------------------------------------------------------
def _track_var_trailing(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for func in tree.body:
        if not isinstance(func, ast.FunctionDef):
            continue
        defined = _defined_names(tree, func)
        for node in ast.walk(func):
            if not isinstance(node, ast.While):
                continue
            body = node.body
            if not body:
                continue
            first = body[0]
            track = None
            if (isinstance(first, ast.Assign) and len(first.targets) == 1
                    and isinstance(first.targets[0], ast.Name)
                    and isinstance(first.value, ast.Subscript)):
                track = first.targets[0].id
            if track is None:
                continue
            spans = []
            for stmt in body[1:]:
                for sub in ast.walk(stmt):
                    if (isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Load)
                            and sub.id not in defined and sub.id != track):
                        spans.append(_span(source, sub))
            if spans:
                out.append(_multi_splice(source, list(set(spans)), track))
    return out

