rule_code:
# ----------------------------------------------------------------------
# Rule: missing lst.remove(max(lst)) causes infinite repeat of the same max
# ----------------------------------------------------------------------
def fix_missing_remove_call(source):
    tree = _parse(source)
    if tree is None:
        return []
    out = []
    for node in ast.walk(tree):
        if not isinstance(node, (ast.While, ast.For)):
            continue
        body = node.body
        max_calls = []
        remove_present = False
        for stmt in body:
            for sub in ast.walk(stmt):
                if (isinstance(sub, ast.Call) and isinstance(sub.func, ast.Name)
                        and sub.func.id == 'max' and len(sub.args) == 1
                        and isinstance(sub.args[0], ast.Name)):
                    max_calls.append((stmt, sub.args[0].id))
                if (isinstance(sub, ast.Call) and isinstance(sub.func, ast.Attribute)
                        and sub.func.attr in ('remove', 'pop')):
                    remove_present = True
        if max_calls and not remove_present:
            stmt, lname = max_calls[0]
            _, e = _span(source, stmt)
            indent = ' ' * stmt.col_offset
            insertion = f"\n{indent}{lname}.remove(max({lname}))"
            out.append(source[:e] + insertion + source[e:])
    return out

def _rule_swap_title_capitalize_to_swapcase(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if node.func.attr in {"title", "capitalize"}:
                txt = ast.get_source_segment(source, node)
                if txt and txt.endswith(".title()") or txt and txt.endswith(".capitalize()"):
                    out.append(_replace_node(source, node, txt.rsplit(".", 1)[0] + ".swapcase()"))
    return out

