def _return_in_loop_to_after_loop(self, source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.For):
            for stmt in node.body:
                if isinstance(stmt, ast.Return):
                    seg = ast.get_source_segment(source, stmt)
                    if seg is not None and "return" in seg:
                        new = seg.replace("return", "break", 1)
                        out.append(_replace_node(source, stmt, new))
    return out

@_safe
def split_reverse_return(source):
    """`return x.reverse()` returns None; reverse then return the name."""
    tree = ast.parse(source)
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Return) and isinstance(node.value, ast.Call):
            call = node.value
            if isinstance(call.func, ast.Attribute) and call.func.attr == 'reverse' \
               and isinstance(call.func.value, ast.Name):
                name = call.func.value.id
                indent = ' ' * node.col_offset
                new_text = "%s.reverse()\n%sreturn %s" % (name, indent, name)
                out.append(_splice(source, node, new_text))
    return _dedupe(out)

