def _lt_to_le_flip(source):
    """Relax/tighten a strict comparison against a literal bound; targets
    off-by-one slips in threshold checks (e.g. `c < n+1` meant `c <= n`)."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare) and len(node.ops) == 1:
            op = node.ops[0]
            if isinstance(op, (ast.Lt, ast.Gt, ast.LtE, ast.GtE)):
                left, right = node.left, node.comparators[0]
                ls, le = _span(source, left)
                rs, re_ = _span(source, right)
                mapping = {ast.Lt: '<=', ast.Gt: '>=', ast.LtE: '<', ast.GtE: '>'}
                new_op = mapping[type(op)]
                new_cmp = source[ls:le] + f" {new_op} " + source[rs:re_]
                candidate = _splice(source, node, new_cmp)
                if candidate != source:
                    out.append(candidate)
    return out

def _fix_contains_unique_day_false_return(source):
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return []
    out = []
    for func in [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name == "contains_unique_day"]:
        for node in ast.walk(func):
            if isinstance(node, ast.Return) and isinstance(node.value, ast.Constant) and node.value.value is True:
                out.append(_splice(source, node, "return False"))
                break
    return out

